test('addLine increases qty and removeLine works after', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  }).value;

  const afterAdd = addLine(invoice, { sku: 'DES-HOUR', qty: 3 }).value;
  assert.equal(afterAdd.lines[0].qty, 8);

